{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-IAEMIf/src/address.js","content":"/**
 * Cell addresses: columns A..ZZ encoded as 1..702, rows 1..999.
 */

/** Convert an upper-cased column letter string ("A".."ZZ") to its 1-based number. */
export function colToNum(letters) {
  let n = 0
  for (const ch of letters) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

/** Convert a 1-based column number back to its letter form. */
export function numToCol(n) {
  if (n <= 26) return String.fromCharCode(64 + n)
  const rest = n - 26
  const first = Math.floor((rest - 1) / 26) + 1
  const second = ((rest - 1) % 26) + 1
  return String.fromCharCode(64 + first) + String.fromCharCode(64 + second)
}

const ADDRESS_SHAPE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/**
 * Parse a word as a cell address. Returns null when the word is not shaped
 * like an address or names a row below 1 - the "outside the addressable
 * range" case, which is distinct from a grammar failure.
 */
export function parseAddress(word) {
  const m = ADDRESS_SHAPE.exec(word)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const col = colToNum(m[1].toUpperCase())
  return { col, row, address: m[1].toUpperCase() + row }
}

/** Compare two addresses by ascending column, then ascending row. */
export function compareAddresses(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}
"}

