{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-IAEMIf/src/lexer.js","content":"/**
 * Tokenizer for a formula body (the text after the leading `=`).
 */

const DIGIT = /[0-9]/
const LETTER = /[A-Za-z]/

/**
 * Split a formula body into tokens. Unrecognized characters become INVALID
 * tokens, which the parser rejects as a grammar failure.
 */
export function tokenize(text) {
  const tokens = []
  let i = 0
  const n = text.length
  while (i < n) {
    const c = text[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (DIGIT.test(c)) {
      let j = i + 1
      while (j < n && DIGIT.test(text[j])) j++
      if (text[j] === '.' && DIGIT.test(text[j + 1] || '')) {
        j++
        while (j < n && DIGIT.test(text[j])) j++
      }
      tokens.push({ type: 'NUMBER', value: text.slice(i, j) })
      i = j
      continue
    }
    if (LETTER.test(c)) {
      let j = i + 1
      while (j < n && LETTER.test(text[j])) j++
      while (j < n && DIGIT.test(text[j])) j++
      tokens.push({ type: 'WORD', value: text.slice(i, j) })
      i = j
      continue
    }
    const two = text.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') {
      tokens.push({ type: 'OP', value: two })
      i += 2
      continue
    }
    if (c === '(') {
      tokens.push({ type: 'LPAREN', value: c })
      i++
      continue
    }
    if (c === ')') {
      tokens.push({ type: 'RPAREN', value: c })
      i++
      continue
    }
    if (c === ',') {
      tokens.push({ type: 'COMMA', value: c })
      i++
      continue
    }
    if (c === ':') {
      tokens.push({ type: 'COLON', value: c })
      i++
      continue
    }
    if ('^*/+-=<>'.includes(c)) {
      tokens.push({ type: 'OP', value: c })
      i++
      continue
    }
    tokens.push({ type: 'INVALID', value: c })
    i++
  }
  tokens.push({ type: 'EOF', value: '' })
  return tokens
}
"}

