{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-IAEMIf/src/parser.js","content":"/**
 * Recursive-descent parser for a formula body. Produces an AST or throws
 * ParseError, which the caller turns into a #ERR! cell value.
 */
import { tokenize } from './lexer.js'

export class ParseError extends Error {}

const COMPARATORS = new Set(['=', '<>', '<=', '<', '>=', '>'])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const tok = this.next()
    if (tok.type !== type) throw new ParseError(`expected ${type}, got ${tok.type}`)
    return tok
  }

  parseFormula() {
    const expr = this.parseExpression()
    this.expect('EOF')
    return expr
  }

  parseExpression() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek().type === 'OP' && COMPARATORS.has(this.peek().value)) {
      const op = this.next().value
      const right = this.parseAdditive()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peek().type === 'OP' && (this.peek().value === '+' || this.peek().value === '-')) {
      const op = this.next().value
      const right = this.parseMultiplicative()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peek().type === 'OP' && (this.peek().value === '*' || this.peek().value === '/')) {
      const op = this.next().value
      const right = this.parsePower()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.peek().type === 'OP' && this.peek().value === '^') {
      this.next()
      const right = this.parsePower()
      return { type: 'binop', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.peek().type === 'OP' && (this.peek().value === '-' || this.peek().value === '+')) {
      const op = this.next().value
      const operand = this.parseUnary()
      return { type: 'unary', op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const tok = this.peek()
    if (tok.type === 'NUMBER') {
      this.next()
      return { type: 'number', value: parseFloat(tok.value) }
    }
    if (tok.type === 'LPAREN') {
      this.next()
      const expr = this.parseExpression()
      this.expect('RPAREN')
