 * Value constructors and formatting shared by parsing literals and by the
 * evaluator.
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export function numberValue(value) {
  return { type: 'number', value }
}

export function textValue(value) {
  return { type: 'text', value }
}

export function booleanValue(value) {
  return { type: 'boolean', value }
}

export function errorValue(token) {
  return { type: 'error', value: token }
}

export const ERR = errorValue('#ERR!')
export const NAME_ERROR = errorValue('#NAME?')
export const VALUE_ERROR = errorValue('#VALUE!')
export const DIV0_ERROR = errorValue('#DIV/0!')
export const REF_ERROR = errorValue('#REF!')
export const CYCLE_ERROR = errorValue('#CYCLE!')

const LITERAL_NUMBER = /^-?[0-9]+(\.[0-9]+)?$/

/** Interpret a cell's raw literal text (never starting with `=`) as a value. */
export function parseLiteral(text) {
  if (text === '') return numberValue(0)
  if (LITERAL_NUMBER.test(text)) return numberValue(parseFloat(text))
  if (ERROR_TOKENS.includes(text)) return errorValue(text)
  return textValue(text)
}

/** Round a finite number to ten significant digits, as JS would print it. */
export function formatNumber(x) {
  if (x === 0) return '0'
  return String(Number(x.toPrecision(10)))
}

/** Render a value the way `values` mode prints it. */
export function formatValue(v) {
  switch (v.type) {
    case 'number':
      return formatNumber(v.value)
    case 'text':
      return v.value
    case 'boolean':
      return v.value ? 'TRUE' : 'FALSE'
    case 'error':
      return v.value
    default:
      throw new Error(`unknown value type ${v.type}`)
  }
}
"}

