 * Parsing of the sheet text format into a map from canonical address to
 * declared content.
 */
import { parseAddress } from './address.js'

export class SheetError extends Error {}

/**
 * Parse sheet text into a Map from canonical address ("A1") to its raw
 * content string. Throws SheetError with a formatted message on the first
 * malformed or duplicate line.
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const raw = lines[i]
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    let j = 0
    while (j < stripped.length && stripped[j] !== ' ' && stripped[j] !== '\t') j++
    const addressText = stripped.slice(0, j)
    let k = j
    while (k < stripped.length && (stripped[k] === ' ' || stripped[k] === '\t')) k++
    if (k === j && k < stripped.length) {
      // unreachable: the loop above already consumed the whitespace run
    }
    // skip exactly one run of spaces/tabs (already consumed above), content is the rest
    let contentStart = j
    if (j < stripped.length) {
      let m = j
      while (m < stripped.length && (stripped[m] === ' ' || stripped[m] === '\t')) m++
      contentStart = m
    }
    const content = stripped.slice(contentStart)

    const parsed = parseAddress(addressText)
    if (!parsed) {
      throw new SheetError(`error: line ${lineNumber}: invalid cell address ${addressText}`)
    }
