 * Evaluation of a compiled sheet into a value for every declared cell, with
 * cycle detection.
 */
import { parseAddress, numToCol } from './address.js'
import { compileCell } from './compile.js'
import { numberValue, textValue, booleanValue, ERR, NAME_ERROR, VALUE_ERROR, DIV0_ERROR, REF_ERROR, CYCLE_ERROR } from './values.js'

const COMPARATOR_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const REDUCER_FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'AVG', 'COUNT'])

/** Evaluate every declared cell. Returns a Map from address to its value. */
export function evaluateSheet(cells) {
  const compiled = new Map()
  for (const [addr, content] of cells) compiled.set(addr, compileCell(content))

  const done = new Map()
  const inProgress = new Set()

  function evaluateCell(addr) {
    if (done.has(addr)) return done.get(addr)
    if (inProgress.has(addr)) return CYCLE_ERROR
    const cell = compiled.get(addr)
    if (!cell) {
      const v = numberValue(0)
      done.set(addr, v)
      return v
    }
    inProgress.add(addr)
    let result
    if (cell.kind === 'literal') {
      result = cell.value
    } else if (cell.ast === null) {
      result = ERR
    } else {
      result = evaluateNode(cell.ast)
    }
    inProgress.delete(addr)
    done.set(addr, result)
    return result
  }

  function resolveAddress(word) {
    const parsed = parseAddress(word)
    if (!parsed) return REF_ERROR
    return evaluateCell(parsed.address)
  }

  function toNumberOperand(v) {
    if (v.type === 'error') return v
    if (v.type === 'number') return v
    if (v.type === 'boolean') return numberValue(v.value ? 1 : 0)
    return VALUE_ERROR
  }

  function arith(op, l, r) {
    let result
    switch (op) {
      case '+':
        result = l + r
        break
      case '-':
        result = l - r
        break
      case '*':
        result = l * r
        break
      case '/':
        result = l / r
        break
      case '^':
        result = Math.pow(l, r)
        break
      default:
        throw new Error(`unknown arithmetic operator ${op}`)
    }
    if (!Number.isFinite(result)) return DIV0_ERROR
    return numberValue(result)
  }

  function kindRank(v) {
    if (v.type === 'number') return 0
    if (v.type === 'text') return 1
    return 2 // boolean
  }

  function compareValues(a, b) {
    const ra = kindRank(a)
    const rb = kindRank(b)
    if (ra !== rb) return ra - rb
    if (a.type === 'number') return a.value - b.value
    if (a.type === 'text') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
    return (a.value ? 1 : 0) - (b.value ? 1 : 0)
  }

  function evalComparison(op, l, r) {
    const c = compareValues(l, r)
    switch (op) {
      case '=':
        return booleanValue(c === 0)
      case '<>':
        return booleanValue(c !== 0)
      case '<':
        return booleanValue(c < 0)
      case '<=':
        return booleanValue(c <= 0)
      case '>':
        return booleanValue(c > 0)
      case '>=':
        return booleanValue(c >= 0)
      default:
        throw new Error(`unknown comparison operator ${op}`)
    }
  }

  function flattenRange(node) {
    const from = parseAddress(node.from)
    const to = parseAddress(node.to)
    if (!from || !to) return [REF_ERROR]
    const c1 = Math.min(from.col, to.col)
    const c2 = Math.max(from.col, to.col)
    const r1 = Math.min(from.row, to.row)
    const r2 = Math.max(from.row, to.row)
    const values = []
    for (let c = c1; c <= c2; c++) {
      for (let r = r1; r <= r2; r++) {
        values.push(evaluateCell(numToCol(c) + r))
      }
    }
    return values
  }

  function flattenArg(node) {
    if (node.type === 'range') return flattenRange(node)
    return [evaluateNode(node)]
  }

  function firstError(values) {
    for (const v of values) if (v.type === 'error') return v
    return null
  }

  function callSum(values) {
    let total = 0
    for (const v of values) {
      const n = toNumberOperand(v)
      if (n.type === 'error') return n
      total += n.value
    }
    return numberValue(total)
  }

  function callMinMax(values, pick) {
    let best = null
    for (const v of values) {
      const n = toNumberOperand(v)
      if (n.type === 'error') return n
      best = best === null ? n.value : pick(best, n.value)
    }
    return numberValue(best)
  }

  function callAvg(values) {
    let total = 0
    for (const v of values) {
      const n = toNumberOperand(v)
      if (n.type === 'error') return n
      total += n.value
    }
    return numberValue(total / values.length)
  }

  function callCount(values) {
    let count = 0
    for (const v of values) if (v.type === 'number') count++
    return numberValue(count)
  }

  function evalIf(node) {
    if (node.args.length !== 3) return ERR
    const condFlat = flattenArg(node.args[0])
    const condErr = firstError(condFlat)
    if (condErr) return condErr
    if (condFlat.length !== 1) return ERR
    const cond = condFlat[0]
    let truthy
    if (cond.type === 'boolean') {
      truthy = cond.value
    } else {
      const n = toNumberOperand(cond)
      if (n.type === 'error') return n
      truthy = n.value !== 0
    }
    const branch = truthy ? node.args[1] : node.args[2]
    const branchFlat = flattenArg(branch)
    const branchErr = firstError(branchFlat)
    if (branchErr) return branchErr
    if (branchFlat.length !== 1) return ERR
    return branchFlat[0]
  }

  function evalAbs(node) {
    if (node.args.length !== 1) return ERR
    const flat = flattenArg(node.args[0])
    const err = firstError(flat)
    if (err) return err
    if (flat.length !== 1) return ERR
    const n = toNumberOperand(flat[0])
    if (n.type === 'error') return n
    return numberValue(Math.abs(n.value))
  }

  function evalReducer(name, node) {
    if (node.args.length < 1) return ERR
    const flat = node.args.flatMap(flattenArg)
    const err = firstError(flat)
    if (err) return err
    switch (name) {
      case 'SUM':
        return callSum(flat)
      case 'MIN':
        return callMinMax(flat, Math.min)
      case 'MAX':
        return callMinMax(flat, Math.max)
      case 'AVG':
        return callAvg(flat)
      case 'COUNT':
        return callCount(flat)
      default:
        throw new Error(`unknown reducer ${name}`)
    }
  }

  function evalCall(node) {
    if (node.name === 'IF') return evalIf(node)
    if (node.name === 'ABS') return evalAbs(node)
    if (REDUCER_FUNCTIONS.has(node.name)) return evalReducer(node.name, node)
    return NAME_ERROR
  }

  function evaluateNode(node) {
    switch (node.type) {
      case 'number':
        return numberValue(node.value)
      case 'boolean':
        return booleanValue(node.value)
      case 'address':
        return resolveAddress(node.word)
      case 'unary': {
        const v = evaluateNode(node.operand)
        const n = toNumberOperand(v)
        if (n.type === 'error') return n
        const value = node.op === '-' ? -n.value : n.value
        if (!Number.isFinite(value)) return DIV0_ERROR
        return numberValue(value)
      }
      case 'binop': {
        const l = evaluateNode(node.left)
        const r = evaluateNode(node.right)
