          if (r.type === 'error') return r
          return evalComparison(node.op, l, r)
        }
        const ln = toNumberOperand(l)
        if (ln.type === 'error') return ln
        const rn = toNumberOperand(r)
        if (rn.type === 'error') return rn
        return arith(node.op, ln.value, rn.value)
      }
