        return evalCall(node)
      case 'range':
        // A range that isn't a direct function argument is a grammar
        // failure, so the parser never produces this node here.
        return ERR
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  const results = new Map()
  for (const addr of cells.keys()) results.set(addr, evaluateCell(addr))
  return results
}

// textValue is re-exported for callers that only need the value constructors.
export { textValue }
