    const set = new Set()
    if (compiled.kind === 'formula' && compiled.ast !== null) {
      walk(compiled.ast, set)
    }
    const addresses = [...set].map((a) => parseAddress(a))
    addresses.sort(compareAddresses)
    result.set(
      addr,
      addresses.map((a) => a.address)
    )
  }
  return result
}
