{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-IAEMIf/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import { readFileSync } from 'node:fs'
import { parseAddress, compareAddresses } from './address.js'
import { parseSheet, SheetError } from './sheet.js'
import { evaluateSheet } from './evaluate.js'
import { computeDeps } from './deps.js'
import { formatValue } from './values.js'

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

function sortedAddresses(cells) {
  return [...cells.keys()].map((a) => parseAddress(a)).sort(compareAddresses).map((a) => a.address)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('error: usage: cli.js values|deps')
    return
  }

  const input = readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(e.message)
      return
    }
    throw e
  }

  const order = sortedAddresses(cells)
  const out = []
  if (mode === 'values') {
    const values = evaluateSheet(cells)
    for (const addr of order) out.push(`${addr}=${formatValue(values.get(addr))}`)
  } else {
    const deps = computeDeps(cells)
    for (const addr of order) {
      const list = deps.get(addr)
      out.push(list.length ? `${addr}: ${list.join(' ')}` : `${addr}:`)
    }
  }
  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

